target.query:
PREFIX ppi: <http://landregistry.data.gov.uk/def/ppi/>
SELECT (COUNT(*) AS ?n) WHERE {
  ?t ppi:transactionDate ?d .
  FILTER(?d >= "2026-07-01"^^<http://www.w3.org/2001/XMLSchema#date>
      && ?d <= "2026-07-31"^^<http://www.w3.org/2001/XMLSchema#date>)
}

